def hasMatch(s: str, p: str) -> bool:
    star_index = p.index('*')
    prefix = p[:star_index]
    suffix = p[star_index + 1:]
    for i in range(len(s) - len(prefix) - len(suffix) + 1):
        if s.startswith(prefix, i) and s.endswith(suffix, i + len(prefix)):
            return True
    return False

from typing import List

def zigzagTraversal(grid: List[List[int]]) -> List[int]:
    result = []
    rows = len(grid)
    cols = len(grid[0])
    for r in range(rows):
        if r % 2 == 0:
            # Traverse left to right
            for c in range(0, cols, 2):
                result.append(grid[r][c])
        else:
            # Traverse right to left
            for c in range(cols - 1, -1, -2):
                result.append(grid[r][c])
    return result

def findValidPair(s: str) -> str:
    from collections import Counter
    counts = Counter(s)
    for i in range(len(s) - 1):
        first_digit = s[i]
        second_digit = s[i + 1]
        if first_digit != second_digit:
            if counts[first_digit] == int(first_digit) and counts[second_digit] == int(second_digit):
                return first_digit + second_digit
    return ""

def hasSpecialSubstring(s: str, k: int) -> bool:
    n = len(s)
    if k > n:
        return False
    for i in range(n - k + 1):
        substring = s[i:i + k]
        if len(set(substring)) == 1:
            if (i == 0 or s[i - 1] != substring[0]) and (i + k == n or s[i + k] != substring[0]):
                return True
    return False

def hasSameDigits(s: str) -> bool:
    while len(s) > 2:
        s = ''.join(str((int(s[i]) + int(s[i + 1])) % 10) for i in range(len(s) - 1))
    return s[0] == s[1]

