from itertools import permutations


def totalNumbers(digits: List[int]) -> int:
    even_count = 0
    distinct_numbers = set()
    for digit in digits:
        if digit % 2 == 0:
            for perm in permutations(digits, 3):
                if perm[0] != 0 and perm[2] == digit:
                    distinct_numbers.add(perm)
    return len(distinct_numbers)

from typing import List

def maxSum(nums: List[int]) -> int:
    unique_nums = set(nums)
    positive_sum = sum(x for x in unique_nums if x > 0)
    if positive_sum > 0:
        return positive_sum
    return max(unique_nums)

